action.command:
python3 -c "
import json, sys
data = json.load(sys.stdin)
tool = data.get('toolName', '')
params = data.get('toolInput', {})

# Collect all string values from the tool parameters to check for sensitive paths
def extract_strings(obj):
    if isinstance(obj, str):
        yield obj
    elif isinstance(obj, dict):
        for v in obj.values():
            yield from extract_strings(v)
    elif isinstance(obj, list):
        for v in obj:
            yield from extract_strings(v)

blocked_patterns = ['.env', '.dev.vars', 'language-lab-private']

for s in extract_strings(params):
    for pat in blocked_patterns:
        if pat in s:
            print(f'Blocked: tool={tool} matched sensitive path pattern \"{pat}\" in parameter: {s}', file=sys.stderr)
            sys.exit(2)
sys.exit(0)
"
